  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.api.ApiHandlers;
  7	import com.pousadamarealta.infrastructure.Database;
  8	import com.pousadamarealta.infrastructure.MessageRepository;
  9	import com.pousadamarealta.infrastructure.ReservationRepository;
 10	import com.pousadamarealta.infrastructure.RoomRepository;
 11	import com.pousadamarealta.service.NotificationService;
 12	import com.pousadamarealta.service.ReportService;
 13	import com.pousadamarealta.service.ReservationService;
 14	import io.javalin.Javalin;
 15	import io.javalin.json.JavalinJackson;
 16	
 17	public class Main {
 18	    public static void main(String[] args) {
 19	        String dbUrl = getEnvOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 20	        String dbUser = getEnvOrDefault("DB_USER", "postgres");
 21	        String dbPassword = getEnvOrDefault("DB_PASSWORD", "postgres");
 22	        int port = Integer.parseInt(getEnvOrDefault("PORT", "7070"));
 23	
 24	        Database database = new Database(dbUrl, dbUser, dbPassword);
 25	        database.initialize();
 26	
 27	        RoomRepository roomRepository = new RoomRepository(database);
 28	        ReservationRepository reservationRepository = new ReservationRepository(database);
 29	        MessageRepository messageRepository = new MessageRepository(database);
 30	
 31	        NotificationService notificationService = new NotificationService(messageRepository);
 32	        ReservationService reservationService = new ReservationService(
 33	                reservationRepository, roomRepository, notificationService);
 34	        ReportService reportService = new ReportService(reservationRepository);
 35	
 36	        ApiHandlers handlers = new ApiHandlers(
 37	                roomRepository, reservationService, messageRepository,
 38	                notificationService, reportService);
 39	
 40	        ObjectMapper objectMapper = new ObjectMapper();
 41	        objectMapper.registerModule(new JavaTimeModule());
 42	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 43	
 44	        Javalin app = Javalin.create(config -> {
 45	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 46	        });
 47	
 48	        app.get("/rooms", handlers::getRooms);
 49	        app.post("/reservations", handlers::createReservation);
 50	        app.get("/reservations/{id}", handlers::getReservation);
 51	        app.post("/reservations/{id}/confirmation", handlers::confirmReservation);
 52	        app.post("/reservations/{id}/cancellation", handlers::cancelReservation);
 53	        app.post("/reservations/{id}/check-in", handlers::checkInReservation);
 54	        app.post("/reservations/{id}/check-out", handlers::checkOutReservation);
 55	        app.get("/reservations/{id}/document", handlers::getDocument);
 56	        app.get("/messages", handlers::getMessages);
 57	        app.get("/reports/occupancy", handlers::getOccupancyReport);
 58	        app.get("/reports/revenue", handlers::getRevenueReport);
 59	        app.get("/reports/tourism-tax", handlers::getTourismTaxReport);
 60	        app.get("/reports/rate-plans", handlers::getRatePlansReport);
 61	
 62	        app.start(port);
 63	
 64	        System.out.println("Sistema da Pousada Maré Alta iniciado na porta " + port);
 65	    }
 66	
 67	    private static String getEnvOrDefault(String name, String defaultValue) {
 68	        String value = System.getenv(name);
 69	        return value != null ? value : defaultValue;
 70	    }
 71	}
 72	package com.pousadamarealta.api;
