 89	public class ApiHandlers {
 90	    private final RoomRepository roomRepository;
 91	    private final ReservationService reservationService;
 92	    private final MessageRepository messageRepository;
 93	    private final NotificationService notificationService;
 94	    private final ReportService reportService;
 95	
 96	    public ApiHandlers(RoomRepository roomRepository,
 97	                      ReservationService reservationService,
 98	                      MessageRepository messageRepository,
 99	                      NotificationService notificationService,
100	                      ReportService reportService) {
101	        this.roomRepository = roomRepository;
102	        this.reservationService = reservationService;
103	        this.messageRepository = messageRepository;
104	        this.notificationService = notificationService;
105	        this.reportService = reportService;
106	    }
107	
108	    public void getRooms(Context ctx) {
109	        var rooms = roomRepository.findAll().stream()
110	                .map(RoomResponse::from)
111	                .collect(Collectors.toList());
112	        ctx.json(rooms);
113	    }
114	
115	    public void createReservation(Context ctx) {
116	        try {
117	            var request = ctx.bodyAsClass(CreateReservationRequest.class);
118	
119	            validateRequest(request);
120	
121	            var reservation = reservationService.createReservation(
122	                    request.roomNumber(),
123	                    request.guestName(),
124	                    request.guestEmail(),
125	                    request.guestCpf(),
126	                    request.checkIn(),
127	                    request.checkOut(),
128	                    request.guests(),
129	                    request.ratePlan()
130	            );
131	
132	            ctx.status(HttpStatus.CREATED).json(ReservationResponse.from(reservation));
133	
134	        } catch (IllegalArgumentException e) {
135	            handleBadRequest(ctx, e.getMessage());
136	        } catch (ReservationService.RoomNotFoundException e) {
137	            handleError(ctx, HttpStatus.NOT_FOUND, "ROOM_NOT_FOUND", e.getMessage());
138	        } catch (ReservationService.RoomUnavailableException e) {
139	            handleError(ctx, HttpStatus.CONFLICT, "ROOM_UNAVAILABLE", e.getMessage());
140	        } catch (ReservationService.CapacityExceededException e) {
141	            handleError(ctx, HttpStatus.UNPROCESSABLE_CONTENT, "CAPACITY_EXCEEDED", e.getMessage());
142	        } catch (ReservationService.InvalidRequestException e) {
143	            handleBadRequest(ctx, e.getMessage());
144	        }
145	    }
146	
147	    private void validateRequest(CreateReservationRequest request) {
148	        if (request.roomNumber() == null || request.guestName() == null ||
149	            request.guestEmail() == null || request.guestCpf() == null ||
150	            request.checkIn() == null || request.checkOut() == null ||
151	            request.guests() == null || request.ratePlan() == null) {
152	            throw new ReservationService.InvalidRequestException("Campos obrigatórios faltando");
153	        }
154	    }
