156	    public void getReservation(Context ctx) {
157	        try {
158	            Long id = Long.parseLong(ctx.pathParam("id"));
159	            var reservation = reservationService.findReservation(id);
160	            ctx.json(ReservationResponse.from(reservation));
161	        } catch (NumberFormatException e) {
162	            handleBadRequest(ctx, "ID inválido");
163	        } catch (ReservationService.ReservationNotFoundException e) {
164	            handleError(ctx, HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", e.getMessage());
165	        }
166	    }
