224	    public void getDocument(Context ctx) {
225	        try {
226	            Long id = Long.parseLong(ctx.pathParam("id"));
227	            Reservation reservation = reservationService.findReservation(id);
228	
229	            if (!reservation.isPaid()) {
230	                handleError(ctx, HttpStatus.CONFLICT, "OPERATION_NOT_ALLOWED",
231	                          "Comprovante só existe para reserva paga");
232	                return;
233	            }
234	
235	            ctx.json(DocumentResponse.from(reservation));
236	        } catch (NumberFormatException e) {
237	            handleBadRequest(ctx, "ID inválido");
238	        } catch (ReservationService.ReservationNotFoundException e) {
239	            handleError(ctx, HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", e.getMessage());
240	        }
241	    }
