250	    public void getOccupancyReport(Context ctx) {
251	        try {
252	            String dateStr = ctx.queryParam("date");
253	            if (dateStr == null) {
254	                handleBadRequest(ctx, "Parâmetro 'date' é obrigatório");
255	                return;
256	            }
257	
258	            LocalDate date = LocalDate.parse(dateStr);
259	            String csv = reportService.generateOccupancyReport(date);
260	            ctx.contentType("text/csv; charset=utf-8").result(csv);
261	
262	        } catch (DateTimeParseException e) {
263	            handleBadRequest(ctx, "Formato de data inválido");
264	        }
265	    }
266	
267	    public void getRevenueReport(Context ctx) {
268	        try {
269	            String monthStr = ctx.queryParam("month");
270	            if (monthStr == null) {
271	                handleBadRequest(ctx, "Parâmetro 'month' é obrigatório");
272	                return;
273	            }
274	
275	            YearMonth month = YearMonth.parse(monthStr);
276	            String csv = reportService.generateRevenueReport(month);
277	            ctx.contentType("text/csv; charset=utf-8").result(csv);
278	
279	        } catch (DateTimeParseException e) {
280	            handleBadRequest(ctx, "Formato de mês inválido");
281	        }
282	    }
283	
284	    public void getTourismTaxReport(Context ctx) {
285	        try {
286	            String monthStr = ctx.queryParam("month");
287	            if (monthStr == null) {
288	                handleBadRequest(ctx, "Parâmetro 'month' é obrigatório");
289	                return;
290	            }
291	
292	            YearMonth month = YearMonth.parse(monthStr);
293	            String csv = reportService.generateTourismTaxReport(month);
294	            ctx.contentType("text/csv; charset=utf-8").result(csv);
295	
296	        } catch (DateTimeParseException e) {
297	            handleBadRequest(ctx, "Formato de mês inválido");
298	        }
299	    }
300	
301	    public void getRatePlansReport(Context ctx) {
302	        try {
303	            String monthStr = ctx.queryParam("month");
304	            if (monthStr == null) {
305	                handleBadRequest(ctx, "Parâmetro 'month' é obrigatório");
306	                return;
307	            }
308	
309	            YearMonth month = YearMonth.parse(monthStr);
310	            String csv = reportService.generateRatePlansReport(month);
311	            ctx.contentType("text/csv; charset=utf-8").result(csv);
312	
313	        } catch (DateTimeParseException e) {
314	            handleBadRequest(ctx, "Formato de mês inválido");
315	        }
316	    }
317	
318	    private void handleBadRequest(Context ctx, String message) {
319	        handleError(ctx, HttpStatus.BAD_REQUEST, "INVALID_REQUEST", message);
320	    }
321	
322	    private void handleError(Context ctx, HttpStatus status, String code, String message) {
323	        ctx.status(status).json(new ErrorResponse(code, message));
324	    }
325	}
326	package com.pousadamarealta.api;
327	
328	public record ErrorResponse(String error, String message) {
329	}

