  6	
  7	import java.math.BigDecimal;
  8	
  9	public class NotificationService {
 10	    private final MessageRepository messageRepository;
 11	
 12	    public NotificationService(MessageRepository messageRepository) {
 13	        this.messageRepository = messageRepository;
 14	    }
 15	
 16	    public void sendConfirmationEmail(Reservation reservation) {
 17	        String subject = "Reserva confirmada - Pousada Maré Alta";
 18	        String body = buildConfirmationEmail(reservation);
 19	        Message message = Message.email(reservation.getGuestEmail(), subject, body);
 20	        messageRepository.save(message);
 21	    }
 22	
 23	    private String buildConfirmationEmail(Reservation reservation) {
 24	        String receipt = buildReceipt(reservation);
 25	        return String.format("""
 26	            Olá, %s!
 27	
 28	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 29	
 30	            %s
 31	
 32	            A entrada é a partir das 14h, e a saída, até as 12h.
 33	            Até breve!""", reservation.getGuestName(), receipt);
 34	    }
 35	
 36	    public String buildReceipt(Reservation reservation) {
 37	        StringBuilder sb = new StringBuilder();
 38	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
 39	        sb.append(String.format("Hóspede: %s (CPF %s)%n",
 40	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
 41	        sb.append(String.format("Quarto: %s (%s)%n",
 42	            reservation.getRoomNumber(), reservation.getRoomType().name()));
 43	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
 44	            formatDate(reservation.getCheckIn()),
 45	            formatDate(reservation.getCheckOut()),
 46	            formatNights(reservation.getNights())));
 47	        sb.append(String.format("Diárias: %s%n", formatMoney(reservation.calculateSubtotal())));
 48	
 49	        BigDecimal discount = reservation.calculateDiscount();
 50	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
 51	            sb.append(String.format("Desconto: %s%n", formatMoney(discount)));
 52	        }
 53	
 54	        sb.append(String.format("Total: %s", formatMoney(reservation.calculateTotal())));
 55	
 56	        return sb.toString();
 57	    }
 58	
 59	    private String formatCpf(String cpf) {
 60	        if (cpf.length() == 11) {
 61	            return String.format("%s.%s.%s-%s",
 62	                cpf.substring(0, 3),
 63	                cpf.substring(3, 6),
 64	                cpf.substring(6, 9),
 65	                cpf.substring(9, 11));
 66	        }
 67	        return cpf;
 68	    }
 69	
 70	    private String formatDate(java.time.LocalDate date) {
 71	        return String.format("%02d/%02d/%04d",
 72	            date.getDayOfMonth(),
 73	            date.getMonthValue(),
 74	            date.getYear());
 75	    }
 76	
 77	    private String formatNights(int nights) {
 78	        return nights == 1 ? "1 diária" : nights + " diárias";
 79	    }
 80	
 81	    private String formatMoney(BigDecimal amount) {
 82	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
 83	    }
 84	}
