153	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
154	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
155	        validateRoom(roomNumber);
156	        validateDates(checkIn, checkOut);
157	        validateGuests(roomNumber, guests);
158	        validateRoomAvailability(roomNumber, checkIn, checkOut, null);
159	
160	        Reservation reservation = Reservation.create(roomNumber, guestName, guestEmail, guestCpf,
