201	    private void validateDates(LocalDate checkIn, LocalDate checkOut) {
202	        if (!checkOut.isAfter(checkIn)) {
203	            throw new InvalidRequestException("A data de saída deve ser posterior à data de entrada");
204	        }
205	    }
206	
207	    private void validateGuests(String roomNumber, int guests) {
208	        if (guests < 1) {
209	            throw new InvalidRequestException("O número de hóspedes deve ser no mínimo 1");
210	        }
211	
212	        Room room = roomRepository.findByNumber(roomNumber).orElseThrow();
213	        if (guests > room.getCapacity()) {
214	            throw new CapacityExceededException(roomNumber, room.getCapacity(), guests);
215	        }
216	    }
217	
218	    private void validateRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
219	        List<Reservation> conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, excludeId);
220	        if (!conflicts.isEmpty()) {
221	            throw new RoomUnavailableException(roomNumber, checkIn, checkOut);
222	        }
223	    }
