227	            super("Reserva não encontrada: " + id);
228	        }
229	    }
230	
231	    public static class RoomNotFoundException extends RuntimeException {
232	        public RoomNotFoundException(String roomNumber) {
233	            super("Quarto não encontrado: " + roomNumber);
234	        }
235	    }
236	
237	    public static class InvalidRequestException extends RuntimeException {
238	        public InvalidRequestException(String message) {
239	            super(message);
240	        }
241	    }
242	
243	    public static class CapacityExceededException extends RuntimeException {
244	        public CapacityExceededException(String roomNumber, int capacity, int guests) {
