 74	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
 75	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
 76	                      ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
 77	        this.id = id;
 78	        this.roomNumber = roomNumber;
 79	        this.guestName = guestName;
 80	        this.guestEmail = guestEmail;
 81	        this.guestCpf = guestCpf;
