 91	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
 92	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 93	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf,
 94	                              checkIn, checkOut, guests, ratePlan,
 95	                              ReservationStatus.PENDING, BigDecimal.ZERO, null);
 96	    }
 97	
 98	    public void confirm() {
 99	        if (status != ReservationStatus.PENDING) {
100	            throw new IllegalStateException("Só é possível confirmar uma reserva pendente");
101	        }
102	        this.status = ReservationStatus.CONFIRMED;
103	        this.amountPaid = calculateTotal();
104	    }
105	
106	    public void checkIn() {
107	        if (status != ReservationStatus.CONFIRMED) {
108	            throw new IllegalStateException("Só é possível fazer check-in de uma reserva confirmada");
109	        }
110	        this.status = ReservationStatus.CHECKED_IN;
111	    }
112	
113	    public void checkOut() {
114	        if (status != ReservationStatus.CHECKED_IN) {
115	            throw new IllegalStateException("Só é possível fazer check-out de uma reserva com check-in");
116	        }
117	        this.status = ReservationStatus.CHECKED_OUT;
118	    }
119	
120	    public void cancel() {
121	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
122	            throw new IllegalStateException("Só é possível cancelar antes do check-in");
123	        }
124	        this.status = ReservationStatus.CANCELLED;
125	        this.refund = calculateRefund();
126	    }
127	
128	    private BigDecimal calculateRefund() {
129	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
130	            return BigDecimal.ZERO;
131	        }
132	        return amountPaid;
133	    }
134	
135	    public int getNights() {
136	        return (int) checkIn.datesUntil(checkOut).count();
137	    }
138	
139	    public BigDecimal calculateSubtotal() {
140	        return checkIn.datesUntil(checkOut)
141	                .map(this::calculateNightRate)
142	                .reduce(BigDecimal.ZERO, BigDecimal::add);
143	    }
144	
145	    private BigDecimal calculateNightRate(LocalDate night) {
146	        BigDecimal baseRate = getRoomNightlyRate();
147	        if (isHighSeason(night)) {
148	            baseRate = baseRate.multiply(new BigDecimal("1.20"));
149	        }
150	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
151	    }
