153	    private boolean isHighSeason(LocalDate date) {
154	        Month month = date.getMonth();
155	        int day = date.getDayOfMonth();
156	
157	        if (month == Month.JULY) {
158	            return true;
159	        }
160	        if (month == Month.DECEMBER && day >= 15) {
161	            return true;
162	        }
163	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
164	            return true;
165	        }
166	        return false;
167	    }
