  2	
  3	import java.sql.Connection;
  4	import java.sql.DriverManager;
  5	import java.sql.SQLException;
  6	import java.sql.Statement;
  7	
  8	public class Database {
  9	    private final String url;
 10	    private final String user;
 11	    private final String password;
 12	
 13	    public Database(String url, String user, String password) {
 14	        this.url = url;
 15	        this.user = user;
 16	        this.password = password;
 17	    }
 18	
 19	    public Connection getConnection() throws SQLException {
 20	        return DriverManager.getConnection(url, user, password);
 21	    }
 22	
 23	    public void initialize() {
 24	        try (Connection conn = getConnection();
 25	             Statement stmt = conn.createStatement()) {
 26	
 27	            stmt.execute("""
 28	                CREATE TABLE IF NOT EXISTS rooms (
 29	                    number VARCHAR(10) PRIMARY KEY,
 30	                    type VARCHAR(20) NOT NULL
 31	                )
 32	                """);
 33	
 34	            stmt.execute("""
 35	                CREATE TABLE IF NOT EXISTS reservations (
 36	                    id BIGSERIAL PRIMARY KEY,
 37	                    room_number VARCHAR(10) NOT NULL,
 38	                    guest_name VARCHAR(255) NOT NULL,
 39	                    guest_email VARCHAR(255) NOT NULL,
 40	                    guest_cpf VARCHAR(14) NOT NULL,
 41	                    check_in DATE NOT NULL,
 42	                    check_out DATE NOT NULL,
 43	                    guests INTEGER NOT NULL,
 44	                    rate_plan VARCHAR(20) NOT NULL,
 45	                    status VARCHAR(20) NOT NULL,
 46	                    amount_paid DECIMAL(10,2) NOT NULL,
 47	                    refund DECIMAL(10,2)
 48	                )
 49	                """);
 50	
 51	            stmt.execute("""
 52	                CREATE TABLE IF NOT EXISTS messages (
 53	                    id BIGSERIAL PRIMARY KEY,
 54	                    channel VARCHAR(20) NOT NULL,
 55	                    recipient VARCHAR(255) NOT NULL,
 56	                    subject VARCHAR(500) NOT NULL,
 57	                    body TEXT NOT NULL
 58	                )
 59	                """);
 60	
 61	            insertRoomsIfNotExist(conn);
 62	
 63	        } catch (SQLException e) {
 64	            throw new RuntimeException("Erro ao inicializar banco de dados", e);
 65	        }
 66	    }
 67	
 68	    private void insertRoomsIfNotExist(Connection conn) throws SQLException {
 69	        String checkQuery = "SELECT COUNT(*) FROM rooms";
 70	        try (var stmt = conn.createStatement();
 71	             var rs = stmt.executeQuery(checkQuery)) {
 72	            if (rs.next() && rs.getInt(1) == 0) {
 73	                String insertQuery = "INSERT INTO rooms (number, type) VALUES (?, ?)";
 74	                try (var pstmt = conn.prepareStatement(insertQuery)) {
 75	                    insertRoom(pstmt, "101", "STANDARD");
 76	                    insertRoom(pstmt, "102", "STANDARD");
 77	                    insertRoom(pstmt, "201", "DELUXE");
 78	                    insertRoom(pstmt, "202", "DELUXE");
 79	                    insertRoom(pstmt, "301", "SUITE");
 80	                }
 81	            }
 82	        }
 83	    }
 84	
 85	    private void insertRoom(java.sql.PreparedStatement pstmt, String number, String type) throws SQLException {
 86	        pstmt.setString(1, number);
 87	        pstmt.setString(2, type);
 88	        pstmt.executeUpdate();
 89	    }
