311	            try (var rs = stmt.executeQuery()) {
312	                while (rs.next()) {
313	                    reservations.add(mapReservation(rs));
314	                }
315	            }
316	        } catch (SQLException e) {
317	            throw new RuntimeException("Erro ao buscar reservas conflitantes", e);
