323	    public List<Reservation> findByMonth(YearMonth month) {
324	        String query = """
325	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
326	                   check_in, check_out, guests, rate_plan, status, amount_paid, refund
327	            FROM reservations
328	            WHERE check_in >= ? AND check_in < ?
329	            ORDER BY check_in, id
330	            """;
331	
332	        List<Reservation> reservations = new ArrayList<>();
333	        LocalDate startDate = month.atDay(1);
334	        LocalDate endDate = month.plusMonths(1).atDay(1);
335	
336	        try (var conn = database.getConnection();
337	             var stmt = conn.prepareStatement(query)) {
338	
339	            stmt.setDate(1, Date.valueOf(startDate));
340	            stmt.setDate(2, Date.valueOf(endDate));
341	
342	            try (var rs = stmt.executeQuery()) {
343	                while (rs.next()) {
344	                    reservations.add(mapReservation(rs));
