132	public abstract class Report {
133	    private static final String POUSADA_NAME = "Pousada Maré Alta";
134	
135	    public String generate() {
136	        StringBuilder csv = new StringBuilder();
137	        csv.append(buildTitle()).append("\n");
138	        csv.append(buildHeader()).append("\n");
139	
140	        List<String> dataLines = buildDataLines();
141	        for (String line : dataLines) {
142	            csv.append(line).append("\n");
143	        }
144	
145	        csv.append(buildTotal());
146	
147	        return csv.toString();
148	    }
149	
150	    private String buildTitle() {
151	        return String.format("%s,%s,%s", POUSADA_NAME, getReportName(), getPeriod());
152	    }
153	
154	    protected abstract String getReportName();
155	    protected abstract String getPeriod();
156	    protected abstract String buildHeader();
157	    protected abstract List<String> buildDataLines();
158	    protected abstract String buildTotal();
159	
160	    protected String formatCsvValue(Object value) {
161	        if (value == null) {
162	            return "";
163	        }
164	        return value.toString();
165	    }
166	
167	    protected String formatCsvDate(java.time.LocalDate date) {
168	        return date.toString();
169	    }
170	
171	    protected String formatCsvMoney(java.math.BigDecimal amount) {
172	        return String.format("%.2f", amount);
173	    }
174	
175	    protected String joinCsvFields(Object... fields) {
176	        return java.util.Arrays.stream(fields)
177	                .map(this::formatCsvValue)
178	                .collect(Collectors.joining(","));
179	    }
180	}
